"use strict";(self.webpackChunkwiki_pt_br=self.webpackChunkwiki_pt_br||[]).push([["33245"],{37797(e){e.exports=JSON.parse('{"tag":{"label":"reComputer","permalink":"/pt-br/tags/re-computer","allTagsPath":"/pt-br/tags","count":6,"items":[{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics_J40/pt_reComputer_Robotics_Hardware_Interfaces_Usage","title":"Hardware e Uso de Interfaces da reComputer Robotics","description":"Este wiki fornece uma introdu\xe7\xe3o abrangente aos recursos de hardware e ao uso das interfaces da placa carrier reComputer Jetson Robotics J401. Ele abrange especifica\xe7\xf5es detalhadas, m\xf3dulos suportados, instru\xe7\xf5es de configura\xe7\xe3o e guias pr\xe1ticos para usar v\xe1rias interfaces, como expans\xe3o de c\xe2mera M.2, Ethernet, USB, CAN, UART, I2C e GMSL2, ajudando os usu\xe1rios a iniciar rapidamente o desenvolvimento em rob\xf3tica na plataforma J401.","permalink":"/pt-br/recomputer_robotics_j401_hardware_interfaces_usage"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics_J40/pt_reComputer_Robotics_Getting_Started","title":"Introdu\xe7\xe3o ao reComputer Robotics","description":"A reComputer Robotics J401 \xe9 uma placa carrier de borda de IA de alto desempenho projetada para aplica\xe7\xf5es avan\xe7adas de rob\xf3tica. Ela suporta m\xf3dulos NVIDIA Jetson Orin Nano e Orin NX nos modos Super/MAXN, oferecendo at\xe9 157 TOPS de poder de computa\xe7\xe3o de IA. A placa oferece amplas op\xe7\xf5es de conectividade, incluindo Ethernet Gigabit dupla, m\xfaltiplas portas USB 3.2, CAN, slots M.2 para m\xf3dulos 5G/Wi-Fi/BT e suporte opcional a c\xe2mera GMSL2. Pr\xe9-instalada com JetPack 6, garante uma implanta\xe7\xe3o perfeita para desenvolvimento em rob\xf3tica. O design robusto suporta ampla faixa de temperatura de opera\xe7\xe3o e inclui um dissipador de calor com ventilador pr\xe9-instalado. A configura\xe7\xe3o envolve gravar o sistema operacional JetPack em um SSD NVMe usando um PC host Ubuntu compat\xedvel, seguida de configura\xe7\xe3o de hardware e uso das interfaces. Especifica\xe7\xf5es detalhadas de hardware, desenhos mec\xe2nicos e recursos t\xe9cnicos s\xe3o fornecidos para desenvolvedores, juntamente com canais de suporte t\xe9cnico e comunidade para solu\xe7\xe3o de problemas e discuss\xe3o.","permalink":"/pt-br/recomputer_robotics_j401_getting_started"},{"id":"Edge/NVIDIA_Jetson/Application/Computer_Vision/pt_industrial_vision_monitoring_on_industrial","title":"Monitoramento de Vis\xe3o Industrial em Ambiente Industrial","description":"Implemente uma demonstra\xe7\xe3o de monitoramento de vis\xe3o industrial em NVIDIA Jetson com detec\xe7\xe3o de objetos YOLO e an\xe1lise de comportamento com VLM","permalink":"/pt-br/industrial_vision_monitoring_on_industrial"},{"id":"Edge/NVIDIA_Jetson/JetPack_7_2/AI_Inference/pt_industrial_vision_monitoring_on_industrial_bk","title":"Monitoramento de Vis\xe3o Industrial em Ambiente Industrial","description":"Implante uma demonstra\xe7\xe3o de monitoramento de vis\xe3o industrial em NVIDIA Jetson com detec\xe7\xe3o de objetos YOLO e an\xe1lise de comportamento com VLM","permalink":"/pt-br/industrial_vision_monitoring_on_industrial_bk"},{"id":"Edge/NVIDIA_Jetson/Application/Computer_Vision/pt_Streaming_Vision_Agent_on_Jetson","title":"Streaming Vision Agent no Jetson","description":"Implante um Streaming Vision Agent no NVIDIA Jetson com mem\xf3ria multimodal cont\xednua dupla Qwen3-VL-2B e interface Ask ao vivo","permalink":"/pt-br/streaming_vision_agent_on_jetson"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Mini/pt_reComputer_Mini_Hardware_Interfaces_Usage","title":"Uso de Hardware e Interfaces do reComputer Mini","description":"Este artigo aborda o hardware e as interfaces da s\xe9rie reComputer Mini J40, incluindo alimenta\xe7\xe3o, display, slots M.2 para Wi\u2011Fi e SSD, portas USB, RTC, gerenciamento de ventoinha e assim por diante. Ele fornece instru\xe7\xf5es de configura\xe7\xe3o e dicas de teste de desempenho para ajudar os usu\xe1rios a expandir seus projetos.","permalink":"/pt-br/recomputer_jetson_mini_hardware_interfaces_usage"}],"unlisted":false}}')}}]);